import { describe, expect, it, vi } from 'vitest';
import {
    createAspect,
    createAdded,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';
import type { Entity } from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const IsActive = trait();
const Mass = trait({ m: 0 });

describe('createAspect', () => {
    it('creates an aspect with id, traits, and schema', () => {
        const Movable = createAspect(Position, Velocity);
        expect(Movable.id).toBeTypeOf('number');
        expect(Movable.traits).toEqual([Position, Velocity]);
        expect(Movable.schema).toMatchObject({ x: 0, y: 0, vx: 0, vy: 0 });
    });

    it('each createAspect call returns a distinct instance', () => {
        const A = createAspect(Position, Velocity);
        const B = createAspect(Position, Velocity);
        expect(A).not.toBe(B);
        expect(A.id).not.toBe(B.id);
    });

    it('requires at least two constituents', () => {
        expect(() => createAspect(Position)).toThrow();
    });

    it('throws on overlapping field names', () => {
        const Other = trait({ x: 100 });
        expect(() => createAspect(Position, Other)).toThrow();
    });

    it('throws on relation constituents', () => {
        const ChildOf = relation();
        expect(() => createAspect(Position, ChildOf)).toThrow();
    });

    it('allows tag traits as constituents', () => {
        const Tagged = createAspect(Position, IsActive);
        expect(Tagged.traits).toContain(IsActive);
        expect(Tagged.schema).not.toHaveProperty('active');
    });

    it('flattens nested aspects', () => {
        const Movable = createAspect(Position, Velocity);
        const ActiveMovable = createAspect(IsActive, Movable);
        expect(ActiveMovable.traits).toEqual([IsActive, Position, Velocity]);
        expect(ActiveMovable.schema).toMatchObject({ x: 0, y: 0, vx: 0, vy: 0 });
    });
});

describe('Aspect entity operations', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => world.reset());

    it('has returns true when every constituent is present', () => {
        const Movable = createAspect(Position, Velocity);
        const entity = world.spawn();
        expect(entity.has(Movable)).toBe(false);
        entity.add(Position);
        expect(entity.has(Movable)).toBe(false);
        entity.add(Velocity);
        expect(entity.has(Movable)).toBe(true);
    });

    it('get returns merged data or undefined', () => {
        const Movable = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }));
        expect(entity.get(Movable)).toBeUndefined();
        entity.add(Velocity({ vx: 3, vy: 4 }));
        expect(entity.get(Movable)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
    });

    it('get includes tag constituents as no fields', () => {
        const Tagged = createAspect(Position, IsActive);
        const entity = world.spawn(Position({ x: 5, y: 6 }), IsActive);
        expect(entity.get(Tagged)).toEqual({ x: 5, y: 6 });
    });

    it('set distributes fields to owning constituents and triggers per-trait change detection', () => {
        const Movable = createAspect(Position, Velocity);
        const entity = world.spawn(Position, Velocity);

        const posCb = vi.fn();
        const velCb = vi.fn();
        world.onChange(Position, posCb);
        world.onChange(Velocity, velCb);

        entity.set(Movable, { x: 10, vy: 20 });
        expect(entity.get(Position)).toMatchObject({ x: 10, y: 0 });
        expect(entity.get(Velocity)).toMatchObject({ vx: 0, vy: 20 });
        expect(posCb).toHaveBeenCalledTimes(1);
        expect(velCb).toHaveBeenCalledTimes(1);
    });

    it('set preserves other fields of atomic constituents', () => {
        const Atomic = trait(() => ({ a: 1, b: 2 }));
        const Combo = createAspect(Atomic, Position);
        const entity = world.spawn(Atomic, Position);
        entity.set(Combo, { a: 9, x: 7 });
        expect(entity.get(Atomic)).toEqual({ a: 9, b: 2 });
        expect(entity.get(Position)).toMatchObject({ x: 7, y: 0 });
    });

    it('add adds only missing constituents and distributes initial values', () => {
        const Movable = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }));

        const addCb = vi.fn();
        world.onAdd(Position, addCb);
        world.onAdd(Velocity, vi.fn());

        entity.add(Movable, { x: 10, vx: 30 });
        expect(entity.has(Position)).toBe(true);
        expect(entity.has(Velocity)).toBe(true);
        expect(entity.get(Position)).toMatchObject({ x: 10, y: 2 });
        expect(entity.get(Velocity)).toMatchObject({ vx: 30, vy: 0 });
        expect(addCb).not.toHaveBeenCalled(); // Position was already present
    });

    it('remove removes all constituent traits', () => {
        const Movable = createAspect(Position, Velocity);
        const entity = world.spawn(Position, Velocity);
        expect(entity.has(Movable)).toBe(true);
        entity.remove(Movable);
        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Velocity)).toBe(false);
    });
});

describe('Aspect queries', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => world.reset());

    it('requires all constituents as a query parameter', () => {
        const Movable = createAspect(Position, Velocity);
        const entityA = world.spawn(Position, Velocity);
        const entityB = world.spawn(Position);
        const entityC = world.spawn(Velocity);

        const results = world.query(Movable);
        expect(results).toHaveLength(1);
        expect(results[0]).toBe(entityA);
        expect(results).not.toContain(entityB);
        expect(results).not.toContain(entityC);
    });

    it('readEach delivers a merged data object', () => {
        const Movable = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

        world.query(Movable).readEach((data) => {
            expect(data).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
        });
    });

    it('readEach works alongside other traits', () => {
        const Movable = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }), Mass({ m: 5 }));

        world.query(Movable, Mass).readEach(([movable, mass]) => {
            expect(movable).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
            expect(mass).toEqual({ m: 5 });
        });
    });

    it('updateEach distributes writes back to constituent stores', () => {
        const Movable = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

        world.query(Movable).updateEach(([movable]) => {
            movable.x += 10;
            movable.vy += 10;
        });

        expect(entity.get(Position)).toMatchObject({ x: 11, y: 2 });
        expect(entity.get(Velocity)).toMatchObject({ vx: 3, vy: 14 });
    });

    it('updateEach triggers change detection for changed constituents', () => {
        const Movable = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

        const posCb = vi.fn();
        const velCb = vi.fn();
        world.onChange(Position, posCb);
        world.onChange(Velocity, velCb);

        world.query(Movable).updateEach(([movable]) => {
            movable.x += 1;
        });

        expect(posCb).toHaveBeenCalledTimes(1);
        expect(velCb).not.toHaveBeenCalled();
    });

    it('Not with an aspect matches entities missing at least one constituent', () => {
        const Movable = createAspect(Position, Velocity);
        const entityA = world.spawn(Position, Velocity);
        const entityB = world.spawn(Position);
        const entityC = world.spawn(Velocity);
        const entityD = world.spawn();

        const results = world.query(Not(Movable));
        expect(results).toHaveLength(3);
        expect(results).not.toContain(entityA);
        expect(results).toContain(entityB);
        expect(results).toContain(entityC);
        expect(results).toContain(entityD);
    });

    it('Changed with an aspect matches when any constituent changed', () => {
        const Movable = createAspect(Position, Velocity);
        const Changed = createChanged();
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

        expect(world.query(Changed(Movable))).toHaveLength(0);

        entity.set(Position, { x: 10, y: 20 });
        const results = world.query(Changed(Movable));
        expect(results).toHaveLength(1);
        expect(results[0]).toBe(entity);

        // After running, query clears
        expect(world.query(Changed(Movable))).toHaveLength(0);

        entity.set(Velocity, { vx: 30, vy: 40 });
        expect(world.query(Changed(Movable))).toHaveLength(1);
    });

    it('Added with an aspect matches the transition to all-present', () => {
        const Movable = createAspect(Position, Velocity);
        const Added = createAdded();
        const entity = world.spawn(Position);

        expect(world.query(Added(Movable))).toHaveLength(0);

        entity.add(Velocity);
        const results = world.query(Added(Movable));
        expect(results).toHaveLength(1);
        expect(results[0]).toBe(entity);
    });

    it('Removed with an aspect matches the transition from all-present', () => {
        const Movable = createAspect(Position, Velocity);
        const Removed = createRemoved();
        const entity = world.spawn(Position, Velocity);

        expect(world.query(Removed(Movable))).toHaveLength(0);

        entity.remove(Position);
        const results = world.query(Removed(Movable));
        expect(results).toHaveLength(1);
        expect(results[0]).toBe(entity);
    });

    it('aspects compose with Or', () => {
        const Movable = createAspect(Position, Velocity);
        const entityA = world.spawn(Position, Velocity);
        const entityB = world.spawn(Position);
        const entityC = world.spawn(Mass);

        const results = world.query(Or(Movable, Mass));
        expect(results).toHaveLength(2);
        expect(results).toContain(entityA);
        expect(results).toContain(entityC);
        expect(results).not.toContain(entityB);
    });
});

describe('Aspect subscriptions', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => world.reset());

    it('onAdd fires when entity transitions from incomplete to complete', () => {
        const Movable = createAspect(Position, Velocity);
        const cb = vi.fn((entity: Entity) => {
            expect(entity.has(Movable)).toBe(true);
        });
        world.onAdd(Movable, cb);

        const entity = world.spawn(Position);
        entity.add(Velocity);
        expect(cb).toHaveBeenCalledTimes(1);

        // No transition when already complete
        entity.add(Velocity);
        expect(cb).toHaveBeenCalledTimes(1);
    });

    it('onRemove fires on reverse transition', () => {
        const Movable = createAspect(Position, Velocity);
        const cb = vi.fn((entity: Entity) => {
            expect(entity.has(Movable)).toBe(false);
        });
        world.onRemove(Movable, cb);

        const entity = world.spawn(Position, Velocity);
        entity.remove(Position);
        expect(cb).toHaveBeenCalledTimes(1);

        // No transition when already incomplete
        entity.remove(Velocity);
        expect(cb).toHaveBeenCalledTimes(1);
    });

    it('onChange fires when any constituent changes while all present', () => {
        const Movable = createAspect(Position, Velocity);
        const cb = vi.fn();
        world.onChange(Movable, cb);

        const entity = world.spawn(Position, Velocity);

        entity.set(Position, { x: 5, y: 5 });
        expect(cb).toHaveBeenCalledTimes(1);

        entity.set(Velocity, { vx: 5, vy: 5 });
        expect(cb).toHaveBeenCalledTimes(2);
    });

    it('onChange does not fire while aspect is incomplete', () => {
        const Movable = createAspect(Position, Velocity);
        const cb = vi.fn();
        world.onChange(Movable, cb);

        const entity = world.spawn(Position);
        entity.set(Position, { x: 5, y: 5 });
        expect(cb).not.toHaveBeenCalled();

        entity.add(Velocity);
        entity.set(Position, { x: 10, y: 10 });
        expect(cb).toHaveBeenCalledTimes(1);
    });
});

describe('Aspect world singleton operations', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => world.reset());

    it('supports has/get/set/add/remove on the world entity', () => {
        const Movable = createAspect(Position, Velocity);

        expect(world.has(Movable)).toBe(false);
        world.add(Movable, { x: 1, vx: 2 });
        expect(world.has(Movable)).toBe(true);
        expect(world.get(Movable)).toMatchObject({ x: 1, vx: 2 });

        world.set(Movable, { y: 3 });
        expect(world.get(Movable)).toMatchObject({ x: 1, y: 3, vx: 2 });

        world.remove(Movable);
        expect(world.has(Movable)).toBe(false);
    });
});
